    rt.define_value(interface.object, "COMMENT_NODE", swb_js::Value::Int(8), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.prototype, "COMMENT_NODE", swb_js::Value::Int(8), swb_js::Attributes::CONSTANT)?;
