    rt.define_value(interface.object, "DOCUMENT_POSITION_PRECEDING", swb_js::Value::Int(2), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.prototype, "DOCUMENT_POSITION_PRECEDING", swb_js::Value::Int(2), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.object, "DOCUMENT_POSITION_FOLLOWING", swb_js::Value::Int(4), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.prototype, "DOCUMENT_POSITION_FOLLOWING", swb_js::Value::Int(4), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.object, "DOCUMENT_POSITION_CONTAINS", swb_js::Value::Int(8), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.prototype, "DOCUMENT_POSITION_CONTAINS", swb_js::Value::Int(8), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.object, "DOCUMENT_POSITION_CONTAINED_BY", swb_js::Value::Int(16), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.prototype, "DOCUMENT_POSITION_CONTAINED_BY", swb_js::Value::Int(16), swb_js::Attributes::CONSTANT)?;
    rt.define_value(interface.object, "DOCUMENT_POSITION_IMPLEMENTATION_SPECIFIC", swb_js::Value::Int(32), swb_js::Attributes::CONSTANT)?;
